INSERT OR REPLACE INTO articles (id, title, url, category, description, year, is_featured, sort_order, ssrn_url, doi_url, tags, created_at) VALUES ('art_featured_01', 'Financial security and stability of the US banking system: comparative analysis and parallels with the Ukrainian experience («Financial security»)', 'https://ssrn.com/abstract=6663479', 'U.S. Banking System', 'Develops an integrated framework for assessing financial system stability by combining Basel III standards, CAMELS methodology, and supervisory indicators. Introduces a multi-layer model linking institutional risk, macroprudential oversight, and systemic resilience, with direct application to regulatory supervision and stress-testing practices.', 2026, 1, 1, 'https://ssrn.com/abstract=6663479', 'https://dx.doi.org/10.2139/ssrn.6663479', 'Financial Security, Financial Stability, U.S. Banking System, Banking Resilience, CAMELS, Basel III, Macroprudential Policy', '2026-05-02T00:00:00.000Z');
INSERT OR REPLACE INTO articles (id, title, url, category, description, year, is_featured, sort_order, ssrn_url, doi_url, tags, created_at) VALUES ('art_us_01', 'Financial security and stability of the US banking system: comparative analysis and parallels with the Ukrainian experience («Financial security»)', 'https://papers.ssrn.com/sol3/papers.cfm?abstract_id=6663479', 'U.S. Banking System', 'Maps the U.S. banking regulatory architecture and constructs quantitative indicators for measuring financial security. Demonstrates how regulatory design translates into measurable system-level resilience.', 2026, 1, 1, '', '', 'Banking Regulation,Financial Stability,Systemic Risk', '2026-05-02T00:00:01.000Z');
INSERT OR REPLACE INTO articles (id, title, url, category, description, year, is_featured, sort_order, ssrn_url, doi_url, tags, created_at) VALUES ('art_us_04', 'Financial security and stability of the US banking system: comparative analysis and parallels with the Ukrainian experience', '#https://papers.ssrn.com/sol3/papers.cfm?abstract_id=6663479', 'U.S. Banking System', 'A comparative study drawing institutional parallels between U.S. banking stability mechanisms and the Ukrainian banking experience under stress conditions. Identifies governance lessons with cross-jurisdictional relevance.', 2026, 1, 1, 'https://papers.ssrn.com/sol3/papers.cfm?abstract_id=6663479', 'Bakalo, Ivan, Financial security and stability of the US banking system: comparative analysis and parallels with the Ukrainian experience («Financial security») (April 07, 2026). Available at SSRN: https://ssrn.com/abstract=6663479 or http://dx.doi.org/10.2139/ssrn.6663479', 'Financial Stability,Institutional Risk,Governance', '2026-05-02T00:00:04.000Z');
INSERT OR REPLACE INTO articles (id, title, url, category, description, year, is_featured, sort_order, ssrn_url, doi_url, tags, created_at) VALUES ('art_ua_01', 'Stress Testing of the Banking System of Ukraine: Tools, Scenarios and Results in Wartime Conditions', 'https://www.linkedin.com/in/ivanbakalo/', 'Financial Stability', 'Applies advanced stress-testing methodologies to the Ukrainian banking system under active wartime conditions. Evaluates institutional resilience and systemic vulnerabilities.', 2024, 1, 2, '', '', 'Systemic Risk,Institutional Risk,Financial Stability', '2026-05-02T00:00:06.000Z');
INSERT OR REPLACE INTO articles (id, title, url, category, description, year, is_featured, sort_order, ssrn_url, doi_url, tags, created_at) VALUES ('art_1783015302967_9z5at', 'Credit-Investment Space of Ukraine''s Regions and Institutional Mechanisms for Its Transformation in the Context of Economic Resilience', 'https://journals.aserspublishing.eu/tpref/article/view/9525', 'Financial Stability', 'Peer-reviewed journal article examining the role of credit-investment systems and institutional mechanisms in strengthening regional economic resilience. The study applies an integrated analytical framework to assess financial stability and institutional transformation under conditions of economic shocks.', 2026, 0, 0, '#', 'https://doi.org/10.14505/tpref.v17.2(38).18', 'financial stability, economic resilience, institutional mechanisms', '2026-07-02T18:01:42.967Z');
INSERT OR REPLACE INTO articles (id, title, url, category, description, year, is_featured, sort_order, ssrn_url, doi_url, tags, created_at) VALUES ('art_1780456399539_ceb6u', 'Financial security as a pillar of the stability of the U.S. banking system', 'https://researcheurope.org/wp-content/uploads/2025/09/re-05.09.2025-16-18.pdf', 'Financial Stability', 'The paper examines financial security as a core component of the U.S. banking systemstability. It analyzes key indicators, regulatory frameworks, and recent challenges, including interestrate hikes, systemic risks, cyber threats, and public debt. Empirical data demonstrate the resilienceof U.S. banks, while highlighting areas requiring continuous monitoring and regulatory vigilance.', 2025, 0, 1, '#', 'https://doi.org/10.64076/iedc250905.06', 'Financial Stability, Financial Security, U.S. Banking System, Banking Resilience, Systemic Stability, Risk Management, Banking Regulation, Macroprudential Policy, Institutional Resilience', '2026-06-03T03:13:19.539Z');
INSERT OR REPLACE INTO articles (id, title, url, category, description, year, is_featured, sort_order, ssrn_url, doi_url, tags, created_at) VALUES ('art_us_02', 'Financial Security of Banking Systems: Conceptual Framework, Indicators, and Evidence from the United States', 'https://ssrn.com/abstract=6507859', 'U.S. Banking System', 'Presents a conceptual framework for evaluating financial security in banking systems and introduces a structured set of indicators derived from the U.S. banking sector. The paper links financial stability, governance, regulatory oversight, and risk assessment into a unified analytical approach.', 2026, 0, 2, 'https://ssrn.com/abstract=6507859', 'https://dx.doi.org/10.2139/ssrn.6507859', 'Financial Security, U.S. Banking System, Banking Indicators, Risk Assessment, Financial Stability, Governance', '2026-05-02T00:00:02.000Z');
INSERT OR REPLACE INTO articles (id, title, url, category, description, year, is_featured, sort_order, ssrn_url, doi_url, tags, created_at) VALUES ('art_us_03', 'Strengthening Financial Security of the U.S. Banking Sector: Regulatory Tools and Practical Risk Mitigation Strategies', 'https://ssrn.com/abstract=6352319', 'U.S. Banking System', 'Analyzes the effectiveness of regulatory instruments and risk mitigation mechanisms in enhancing resilience of the U.S. banking sector. Proposes a structured set of supervisory and policy tools for managing systemic risk, improving banking resilience, and strengthening macroprudential oversight under conditions of economic uncertainty.', 2026, 0, 3, 'https://ssrn.com/abstract=6352319', 'https://dx.doi.org/10.2139/ssrn.6352319', 'Risk Management,Banking Regulation,Systemic Risk,Macroprudential Policy,Banking Supervision,Financial Stability', '2026-05-02T00:00:03.000Z');
INSERT OR REPLACE INTO articles (id, title, url, category, description, year, is_featured, sort_order, ssrn_url, doi_url, tags, created_at) VALUES ('art_1778076568291', 'Regulatory Architecture and Quantitative Indicators of Financial Security in the U.S. Banking System', 'https://desymp.promonograph.org/index.php/sge/issue/view/sge46-04/sge46-04', 'U.S. Banking System', 'Analyzes the regulatory architecture supporting financial security in the U.S. banking sector and develops a system of quantitative indicators for measuring banking resilience, prudential soundness, and systemic stability under changing economic conditions.', 2026, 0, 4, '', 'https://doi.org/10.30890/2709-2313.2026-46-04', 'Banking Regulation, Financial Security, Banking Indicators, Macroprudential Policy, Governance, U.S. Banking System', '2026-05-06T14:09:28.291Z');
INSERT OR REPLACE INTO articles (id, title, url, category, description, year, is_featured, sort_order, ssrn_url, doi_url, tags, created_at) VALUES ('art_1778077029349', 'Integrated Financial Security Framework for Banking Systems: A Risk-Based and Managerial Approach to Financial Stability', 'https://ssrn.com/abstract=6709439', 'Risk & Regulation', 'This paper develops an integrated, risk-based framework for assessing financial security in modern banking systems, with a focus on the United States. It provides practical tools for evaluating systemic risk, capital adequacy, and institutional resilience. The study addresses emerging threats, including interest rate shocks and technology-driven risks such as cybersecurity and AI. Its findings contribute to strengthening financial stability, regulatory oversight, and risk management practices in the U.S. banking sector.', 2026, 0, 5, 'https://ssrn.com/abstract=6709439', 'https://dx.doi.org/10.2139/ssrn.6709439', 'Banking Regulation, Financial Indicators, Governance, Banking Supervision, Systemic Risk, Macroprudential Policy', '2026-05-06T14:17:09.349Z');
INSERT OR REPLACE INTO articles (id, title, url, category, description, year, is_featured, sort_order, ssrn_url, doi_url, tags, created_at) VALUES ('art_1780454487617_doj8g', 'Integrated Financial Security Framework for Banking Systems: A Risk-Based and Governance-Driven Model for Systemic Stability', 'https://ssrn.com/abstract=6720603', 'Risk & Regulation', 'Proposes a governance-driven analytical model for evaluating systemic stability within banking systems. Integrates institutional governance, risk management structures, and macroprudential oversight into a unified framework for assessing systemic resilience.', 2026, 0, 6, 'https://ssrn.com/abstract=6720603', 'https://dx.doi.org/10.2139/ssrn.6720603', 'Systemic Risk, Governance, Financial Stability, Banking Regulation, Banking Resilience, Research Methodology', '2026-06-03T02:41:27.617Z');
INSERT OR REPLACE INTO articles (id, title, url, category, description, year, is_featured, sort_order, ssrn_url, doi_url, tags, created_at) VALUES ('art_1780454885593_8l7pe', 'Integrated Financial Security Diagnostics System: Concept, Methodological Tools and Verification of Results', 'https://journal.eae.com.ua/index.php/journal/article/view/657', 'Research & Methodology', 'Develops a comprehensive diagnostic framework for assessing financial security through integrated risk indicators, analytical tools, and multi-dimensional evaluation criteria. The study introduces methodological instruments for measuring financial resilience, validating financial security models, and supporting evidence-based risk assessment in banking institutions and financial systems.', 2025, 0, 9, '#', 'http://doi.org/10.32750/2025-0450', 'Financial Security, Risk Assessment, Diagnostics System, Research Methodology, Financial Stability, Banking Systems, Integrated Indicators, Risk Measurement, Model Verification, Analytical Framework', '2026-06-03T02:48:05.593Z');
INSERT OR REPLACE INTO articles (id, title, url, category, description, year, is_featured, sort_order, ssrn_url, doi_url, tags, created_at) VALUES ('art_1780455693383_1e867', 'Financial Stability of the Banking System of the European Union: Practical Aspects and Strategic Paradigms', 'https://conferencii.com/arc/Conferencii_2025_12(38).pdf', 'Financial Stability', 'Examines financial stability mechanisms within the European Union banking system, focusing on regulatory architecture, systemic risk management, and macroprudential supervision. Provides comparative insights into supervisory models, banking resilience, and strategic approaches to strengthening financial stability.', 2025, 0, 9, '#', 'http://doi.org/10.51586/2025_12_38', 'Financial Stability, European Banking System, Banking Resilience, Systemic Risk, Banking Regulation, Macroprudential Policy, Financial Security, EU Banking Sector, Comparative Analysis, Strategic Paradigms', '2026-06-03T03:01:33.383Z');
INSERT OR REPLACE INTO articles (id, title, url, category, description, year, is_featured, sort_order, ssrn_url, doi_url, tags, created_at) VALUES ('art_1778077504781', 'Stress Testing of the Banking System of Ukraine: Tools, Scenarios and Results in Wartime Conditions', 'https://ssrn.com/abstract=6222758', 'Financial Stability', 'Analyzes stress-testing methodologies applied to banking systems under extreme economic conditions.
Demonstrates the role of scenario analysis and risk forecasting in evaluating systemic resilience.', 2025, 0, 11, 'https://ssrn.com/abstract=6222758', 'https://doi.org/10.25264/2311-5149-2025-37(65)-37-42', 'Stress Testing, Ukraine, Banking Stability, Scenario Analysis, Financial Resilience', '2026-05-06T14:25:04.781Z');
INSERT OR REPLACE INTO articles (id, title, url, category, description, year, is_featured, sort_order, ssrn_url, doi_url, tags, created_at) VALUES ('art_1780456604588_qhjse', 'Theoretical and Methodological Aspects of Assessing the Financial Security of Banks', 'https://www.researchgate.net/profile/Ivan-Bakalo-2/publication/398839992_INTERNATIONAL-EXPERIENCE-IN-SCIENTIFIC-RESEARCH-18-201225/links/694470460c98040d481ec7d4/INTERNATIONAL-EXPERIENCE-IN-SCIENTIFIC-RESEARCH-18-201225.pdf#page=585', 'Research & Methodology', 'https://www.researchgate.net/profile/Ivan-Bakalo-2/publication/398839992_INTERNATIONAL-EXPERIENCE-IN-SCIENTIFIC-RESEARCH-18-201225/links/694470460c98040d481ec7d4/INTERNATIONAL-EXPERIENCE-IN-SCIENTIFIC-RESEARCH-18-201225.pdf#page=585', 2025, 0, 11, '#', '#', 'Research Methodology, Financial Security, Banking Sector, Risk Assessment, Analytical Framework, Banking Stability, Evaluation Indicators, Methodological Approach, Financial Diagnostics', '2026-06-03T03:16:44.588Z');
